    public static function names(): array
    {
        return array_keys(self::ICONS);
    }

    public static function svg(string $name, string $class = 'icon'): string
    {
        if (!isset(self::ICONS[$name])) {
            return '';
        }
        [$style, , $paths] = self::ICONS[$name];
        $attrs = $style === 'solid' ? 'fill="currentColor"' : 'fill="none" stroke-width="1.5" stroke="currentColor"';

        return '<svg xmlns="http://www.w3.org/2000/svg" class="' . htmlspecialchars($class, ENT_QUOTES) . '" viewBox="0 0 24 24" ' . $attrs
             . ' aria-hidden="true" focusable="false">' . $paths . '</svg>';
    }
